insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 1, 'rackQueue models the IBAFO loading rack as an M/M/c queue. What does that model assume about the trucks and the bays?', '["Trucks arrive on a booked timetable, each load takes exactly the mean minutes, and there are c bays.", "Trucks arrive at random, and a truck that finds c bays busy gives up and drives away without loading.", "Trucks arrive at random around a mean rate, each holds a bay for a random time around a mean, and there are c bays.", "Trucks arrive at random, and a priority lane serves the trucks with the shortest loads before the rest."]'::jsonb, 2, 'The first M is random arrivals around a stated mean rate, the second M a random time on the bay around a stated mean, and c is the bay count. Nothing else is assumed: no appointment system, no priority lane and no truck that gives up.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 2, 'The IBAFO rack is called with 9 arrivals an hour, 4 bays and a load time typed as 0 minutes. What does the engine answer?', '["REFUSED: Arrival rate and load time are both needed.", "REFUSED: The number of bays must be a whole number, one or more.", "REFUSED: The rack cannot keep up with arrivals. The queue grows without limit, so no average waiting time exists. Add a bay, load faster, or spread the arrivals.", "No refusal: stable true and a mean wait of none."]'::jsonb, 0, 'A load that takes no time is a missing measurement. The digest''s refusal table prints the load time of 0 against 9 arrivals and 4 bays with the sentence about the arrival rate and the load time, the same sentence a blank load time gets.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 3, 'At IBAFO the offered load is 3.6000 erlangs. How does rackQueue form it?', '["Arrivals per hour / (60 / load minutes) / bays.", "Arrivals per hour x bays / (60 / load minutes).", "Probability of waiting x bays.", "Arrivals per hour / (60 / load minutes)."]'::jsonb, 3, 'The digest prints offered load (erlangs) = arrivals per hour / (60 / load minutes), and utilisation = offered load / bays. Dividing the offered load by the bays again gives the utilisation, 0.900000. The bay count is not in the offered load, and neither is the probability of waiting, 0.787753.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 4, 'The bay sweep holds IBAFO''s 9 arrivals an hour and 24 minute loads. Going from 4 bays to 5, which printed figure moves, and how?', '["The offered load, from 3.6000 to 2.8000 erlangs.", "The utilisation, from 0.900000 to 0.720000.", "The probability of waiting, from 0.900000 to 0.720000.", "Neither ratio; both come from the traffic."]'::jsonb, 1, 'Utilisation = offered load / bays, and the bay sweep prints it falling from 0.900000 to 0.720000. The bay sweep prints no offered load, and the offered load formula, arrivals per hour / (60 / load minutes), has no bays in it. The 2.8000 erlangs belong to the arrivals sweep at 7 arrivals an hour, and the probability of waiting moves from 0.787753 to 0.410394.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 5, 'IBAFO''s rack prints a utilisation of 0.900000 and a probability of waiting of 0.787753. What does 0.787753 measure?', '["The share of each bay''s hour spent loading, across the 4 bays.", "The chance a truck finding every bay busy is turned away.", "The chance that an arriving truck has to wait for a bay.", "The share of the day''s 216 trucks that load within the mean load minutes."]'::jsonb, 2, 'The digest names it: the probability that an arriving truck waits is Erlang C. 0.900000 is the utilisation, offered load / bays. Erlang B, the rack where a truck that finds every bay busy leaves, is not exported by the engine, and 216 is the trucks per day at this arrival rate.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 6, 'The 6 bay rack at 9 arrivals an hour and the 4 bay rack at 6 arrivals an hour both print a utilisation of 0.600000. Which probability of waiting does the 6 bay rack print?', '["0.287043", "0.410394", "0.600000", "0.196566"]'::jsonb, 3, 'The bay sweep prints 0.196566 for 6 bays at 9 arrivals. The arrivals sweep prints 0.287043 for 4 bays at 6 arrivals, and the load minutes sweep prints the same 0.287043 for 4 bays at 16 minutes a load, also at 0.600000. The same utilisation prints two different probabilities. 0.410394 is the 5 bay row and 0.600000 is the utilisation itself.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 7, 'The digest prints an Erlang B of 0.270685 beside the IBAFO rack''s Erlang C of 0.787753. Where does that Erlang B come from?', '["rackQueue exports it as a blocking probability.", "The engine''s probability of waiting at 16 minute loads.", "The utilisation times the engine''s Erlang C.", "The digest works it out from the engine''s Erlang C by an identity."]'::jsonb, 3, 'The engine builds Erlang C from the Erlang B recursion and exports only Erlang C. The digest derives B = C x (1 - utilisation) / (1 - utilisation x C), which gives 0.270685 on the IBAFO rack, and labels it as worked out from the engine''s figure.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 8, 'What rack does the derived Erlang B of 0.270685 describe?', '["The IBAFO rack as it runs, where a truck that finds every bay busy waits in the yard.", "A rack with no queue, where a truck that finds every bay busy leaves.", "A rack where every truck waits in the yard.", "A rack of one bay, where B and C agree."]'::jsonb, 1, 'The digest defines this Erlang B for a rack with NO queue, in which a truck that meets every bay busy drives off, and works it out for IBAFO as 0.270685. rackQueue runs the M/M/c queue instead and reports its Erlang C, 0.787753.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 9, 'The load minutes are swept at 9 arrivals an hour on 4 bays. At 20 minutes a load, which figure is rackQueue''s probability of waiting?', '["0.206107", "0.750000", "0.509434", "0.642160"]'::jsonb, 2, 'At 20 minutes the engine''s Erlang C is 0.509434. The 0.206107 is the Erlang B the digest derives from that Erlang C, 0.750000 is the utilisation, and 0.642160 is the probability of waiting at 22 minutes a load.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 10, 'The IBAFO rack is called with its 9 arrivals and 24 minute loads and a bay count of 2.5. What happens?', '["The engine rounds the bay count up to 3 and prints the unstable row with a wait of none.", "REFUSED: Arrival rate and load time are both needed.", "The engine runs the Erlang recursion on 2.5 bays and prints a utilisation of 1.200000.", "REFUSED: The number of bays must be a whole number, one or more."]'::jsonb, 3, 'The refusal table prints this sentence for 2.5 bays, as for 0 bays and for none. The engine does not round the bay count. 1.200000 is the utilisation of the 3 bay rack in the bay sweep, and the sentence about the arrival rate and the load time belongs to a missing or zero load time.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 11, 'The bay count is passed as none on an otherwise complete IBAFO call. Which answer does the engine give?', '["The whole number sentence, the same one it gives for 0 bays.", "A run on 4 bays, the typical count it keeps.", "The sentence asking for arrival rate and load time.", "The offered load alone, with every probability none."]'::jsonb, 0, 'The refusal table prints the same sentence for 0, 2.5 and none: "The number of bays must be a whole number, one or more." The engine runs no rack on a typical count.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 12, 'What does the bay sweep print for the 3 bay rack at 9 arrivals an hour?', '["Stable false, probability of waiting 1.200000, its utilisation.", "Stable false, probability of waiting 1.000000.", "Stable true, probability of waiting 0.787753.", "Stable false, probability of waiting none."]'::jsonb, 1, 'At 3 bays the utilisation is 1.200000, the arriving work needs more bay time than the rack has, and every arriving truck waits: the probability prints 1.000000 and the rack is marked unstable. It is the mean wait and mean queue that print none.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 13, 'Among the racks the bay sweep prints at 9 arrivals an hour, which is the smallest whole rack the engine marks stable?', '["3 bays, at a utilisation of 1.200000, since 3.6000 erlangs rounds down to it.", "5 bays, the first row whose probability of waiting falls below 0.787753.", "6 bays, where the utilisation of 0.600000 matches the 4 bay rack at 6 arrivals.", "4 bays, at a utilisation of 0.900000."]'::jsonb, 3, 'The bay sweep marks 3 bays stable false at a utilisation of 1.200000 and 4 bays stable true at 0.900000. At 4 bays an arriving truck still waits with a probability of 0.787753, and the mean wait is 47.2652 minutes.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 14, 'The engine counts 216 trucks a day at IBAFO''s arrival rate. What is that count?', '["The trucks the 4 bays can load in a day before the rack stops being stable.", "The trucks that load without waiting, the day''s share not caught by the Erlang C.", "The trucks a day at the rack''s mean arrival rate of 9 an hour.", "The day''s liftings in trucks, the divisor the tank farm uses for days of cover."]'::jsonb, 2, 'The digest labels it trucks per day at this arrival rate, and the rate is 9 arrivals an hour. The bays do not enter it, and neither does the probability of waiting. The tank farm divides by its daily throughput in m3, 2640.000 m3.'),
  ('supply', 'intermediate', 'module', 'm01-the-loading-rack-as-a-queue', 15, 'A depot turns trucks away at its gate when every bay is busy. Why note that beside rackQueue''s probability of waiting?', '["rackQueue models an M/M/c queue, and the no-queue Erlang B is not exported.", "The engine then switches to Erlang B and prints the blocking probability instead.", "rackQueue counts the turned away trucks in its mean queue length of 7.0898.", "The printed probability counts the turned away trucks twice, once at the gate and once queued."]'::jsonb, 0, 'The engine''s figure is the Erlang C of an M/M/c queue, 0.787753, in which a truck that finds every bay busy waits. The digest works the no-queue Erlang B, 0.270685, out of it by an identity, and the engine exports none. Little''s law gives its queue length of 7.0898 from the arrivals and the mean wait.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 1, 'rackQueue''s mean wait = Erlang C / (bays x service rate - arrivals). Which printed IBAFO figure is its numerator?', '["The utilisation, 0.900000.", "The probability of waiting, 0.787753.", "The Erlang B worked out from it, 0.270685.", "The offered load of the traffic, 3.6000 erlangs."]'::jsonb, 1, 'The IBAFO table prints the probability of waiting as Erlang C, 0.787753, and the mean wait formula divides that Erlang C. 0.900000 is the utilisation and 3.6000 erlangs the offered load. 0.270685 is the Erlang B the digest works out from the Erlang C, and the engine does not export it.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 2, 'IBAFO''s mean wait is 47.2652 minutes. Which trucks is that figure averaged over?', '["Only the trucks that queue, since a truck that finds a free bay has no wait to record.", "The trucks that queue in the peak hour, the only hour the rack is ever full.", "The trucks on the bays and in the yard together, the whole visit of each one.", "Every arriving truck, the ones that load at once counted as zero."]'::jsonb, 3, 'The digest says the engine''s averageWaitMinutes averages over every truck, the ones that load at once included. The mean wait of a truck that does queue, 47.2652 / 0.787753 = 60.0000 minutes, is worked out in the digest. The mean time on site is a separate row of the table.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 3, 'A driver who queued asks what the average wait is for trucks that actually queue at IBAFO. Which figure does the digest give, worked out from the engine''s figures?', '["60.0000 minutes, the mean wait over the probability of waiting.", "47.2652 minutes, the engine''s averageWaitMinutes.", "7.0353 minutes, the 5 bay wait.", "24 minutes, the mean time on the bay."]'::jsonb, 0, 'The digest prints 47.2652 / 0.787753 = 60.0000 minutes and labels it as worked out from the engine''s figures. The engine''s 47.2652 averages over every truck; dividing by the probability of waiting leaves the average over the trucks that queue.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 4, 'Read the arrivals sweep at 8 trucks an hour on IBAFO''s 4 bays. Which utilisation, probability of waiting and mean wait does that row print, in that order?', '["0.700000, 0.428654 and 8.5731 minutes.", "0.800000, 0.787753 and 17.8930 minutes.", "0.800000, 0.596432 and 17.8930 minutes.", "0.800000, 0.596432 and 47.2652 minutes."]'::jsonb, 2, 'The arrivals sweep prints a utilisation of 0.800000, a probability of waiting of 0.596432 and a mean wait of 17.8930 minutes at 8 arrivals. 0.428654 and 8.5731 minutes are the 7 arrival row, and 0.787753 and 47.2652 minutes the 9 arrival row.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 5, 'The digest checks the queue length by Little''s law: 9 x 47.2652 / 60 = 7.0898. Why is the division by 60 there?', '["It turns 9 arrivals an hour into arrivals a minute for each bay.", "It spreads the queue over a bay''s hour.", "It converts the load time to a rate.", "It turns the wait from minutes into hours."]'::jsonb, 3, 'Little''s law reads queue length = arrivals per hour x mean wait in hours. The arrivals are per hour, the wait prints in minutes, so the wait is divided by 60 to match. The result agrees with the engine''s own queue length of 7.0898 trucks.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 6, 'What does IBAFO''s mean queue length of 7.0898 trucks count?', '["Trucks waiting and trucks on the bays, on average.", "Trucks waiting for a bay, on average.", "The most trucks the yard holds at the busiest moment.", "Trucks waiting for a bay in the peak hour alone."]'::jsonb, 1, 'The digest reaches 7.0898 by Little''s law from the mean wait: 9 x 47.2652 / 60, the arrivals times the wait in hours. The time on the bay is not in that line. The figure is a mean queue length, so it is no maximum, and rackQueue has no peak hour.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 7, 'The load minutes are swept on IBAFO''s 4 bays at 9 arrivals an hour. If the mean load drops from 24 minutes to 20, which printed pair describes the change?', '["Mean wait from 47.2652 minutes to 7.0353, the fifth bay row.", "Mean wait to 20.1822 minutes.", "Mean wait from 47.2652 minutes to 10.1887.", "Probability of waiting from 0.787753 to 0.410394."]'::jsonb, 2, 'The load minutes sweep prints 10.1887 minutes at 20 minutes a load. The 20.1822 minutes is the 22 minute row; 7.0353 minutes and 0.410394 belong to the bay sweep at 5 bays, a different lever.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 8, 'The arrivals rise to 10 an hour on IBAFO''s 4 bays with 24 minute loads. What does rackQueue answer?', '["REFUSED: The rack cannot keep up with arrivals. The queue grows without limit, so no average waiting time exists. Add a bay, load faster, or spread the arrivals.", "REFUSED: Arrival rate and load time are both needed.", "REFUSED: The number of bays must be a whole number, one or more.", "No refusal: stable true, mean wait 245.7297 minutes."]'::jsonb, 0, 'At 10 arrivals the utilisation reaches 1.000000 and the arriving work equals what the bays can load. The engine does not print a very large wait; it refuses. 245.7297 minutes is the 26 minute row of the load minutes sweep at 9 arrivals.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 9, 'At 10 arrivals an hour the engine refuses a mean wait. What does it still report for that row?', '["Stable true and a probability of waiting of 0.891419.", "Stable false and a probability of waiting of 1.000000.", "Stable false and a mean queue of 7.0898 trucks, the last figure it could form.", "Nothing at all, since a refused call prints no figure."]'::jsonb, 1, 'The engine reports what it can: stable false, probability of waiting 1.000000, mean wait none. Every arriving truck waits. 0.891419 is the probability at 9.5 arrivals, the row before it.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 10, 'Why does the engine print no mean wait at a utilisation of exactly 1.000000?', '["The wait exceeds a ceiling of minutes that the engine refuses to print past.", "Erlang C can only be formed below one, so the recursion stops before the wait.", "A mean wait needs a derived Erlang B, which cannot be formed at one.", "The queue grows without limit, so no average waiting time exists."]'::jsonb, 3, 'The refusal gives the engine''s own reason: "The queue grows without limit, so no average waiting time exists." The engine still forms Erlang C at that row and prints 1.000000, and the mean wait formula divides the Erlang C, with no Erlang B in it.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 11, 'The refusal names three remedies. Which input does "load faster" change?', '["The bay count, which lowers the utilisation.", "The arrivals in the peak hour.", "The mean load minutes, which lowers the offered load.", "The rack''s queueing hours, typed as an allowance."]'::jsonb, 2, 'Adding a bay raises the denominator of the utilisation; spreading the arrivals lowers the peak arrivals; loading faster shortens the load minutes and so lowers the offered load. On 4 bays at 9 arrivals the load minutes sweep prints 10.1887 minutes of wait at 20 minutes a load.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 12, 'IBAFO adds a fifth bay at the same 9 arrivals an hour and 24 minute loads. Which figure is the same for the 5 bay rack as for the 4 bay rack?', '["The offered load, 3.6000 erlangs.", "The utilisation, 0.900000.", "The mean queue, 7.0898 trucks.", "The probability of waiting, 0.787753."]'::jsonb, 0, 'Offered load = arrivals per hour / (60 / load minutes); the bay count is not in it, so both racks carry 3.6000 erlangs. At 5 bays the sweep prints a utilisation of 0.720000, a probability of 0.410394 and a queue of 1.0553 trucks.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 13, 'What does a decision to build IBAFO''s fifth bay need that rackQueue does not print?', '["The fifth bay''s probability of waiting, which the sweep leaves out.", "The mean queue at 5 bays, since only the 4 bay rack has one.", "The offered load at 5 bays, since it changes with each bay added.", "A cost for the bay and a cost for a truck''s hour."]'::jsonb, 3, 'The sweep prints the service consequence of each whole rack: at 5 bays a probability of 0.410394, a wait of 7.0353 minutes and a queue of 1.0553 trucks. The rack model prices nothing, so a bay decision joins the sweep to costs from outside the engine.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 14, 'Traffic at IBAFO grows from 9 to 9.5 arrivals an hour on the same 4 bays. How far does the average wait climb?', '["From 47.2652 minutes to 245.7297, the wait at 26 minute loads.", "From 47.2652 minutes to 106.9703.", "From 17.8930 minutes to 47.2652.", "From 47.2652 minutes to none."]'::jsonb, 1, 'The arrivals sweep prints 106.9703 minutes at 9.5 arrivals an hour, and the refusal comes at 10. 17.8930 minutes is the row at 8 arrivals, and 245.7297 minutes is a load minutes row.'),
  ('supply', 'intermediate', 'module', 'm02-waiting-time-and-a-full-rack', 15, 'Why does the digest print the Little''s law line beside the engine''s queue length?', '["It shows the yard never holds more than 7.0898 trucks at any moment.", "It derives the Erlang B of the rack from the engine''s queue length.", "It reaches the engine''s 7.0898 a second way, from the arrivals and the mean wait.", "It replaces the engine''s figure, which the Erlang recursion cannot form."]'::jsonb, 2, 'The digest prints Little''s law, queue length = arrivals per hour x mean wait in hours: 9 x 47.2652 / 60 = 7.0898, and beside it the engine''s queue length, 7.0898. The Erlang B is worked out from the Erlang C, and a mean queue is no maximum.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 1, 'What is a tank''s heel in the IBAFO farm?', '["A figure the engine takes from PRODUCT_REFERENCE for each product.", "The free water below the product, which the dip less the water height removes.", "Each tank''s own volume below which none of its stock is pumpable.", "The room left above the stock, which a receipt must fit into."]'::jsonb, 2, 'tankFarmCover counts each tank''s pumpable stock as its stock above its own heel, never below zero, and working capacity is capacity less heel. Each tank carries its own heel: IB-T4 85.000 m3 and IB-T3 150.000 m3. PRODUCT_REFERENCE carries typical densities, free water is taken off at the dip, and capacity less stock is the ullage.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 2, 'tankFarmCover divides by one farm figure to get turns a year. Which one?', '["The working capacity, 21845.000 m3.", "The capacity, 22500.000 m3.", "The ullage, 11767.300 m3.", "The pumpable stock, 10123.000 m3."]'::jsonb, 0, 'Turns a year = daily throughput x 365 / working capacity, and working capacity is capacity less heel: the farm table prints 22500.000 m3, 655.000 m3 and 21845.000 m3.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 3, 'IB-T2 holds 164.700 m3 of petrol against a heel of 210.000 m3. What pumpable stock does the engine give it?', '["164.700 m3", "210.000 m3", "7335.300 m3", "0.000 m3"]'::jsonb, 3, 'Pumpable stock is counted above each tank''s own heel and floored at zero. IB-T2''s 164.700 m3 sits under 210.000 m3, so the row reads 0.000 m3; 7335.300 m3 is its ullage.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 4, 'Which figure does tankFarmCover report as the IBAFO farm''s pumpable stock?', '["10077.700 m3", "10123.000 m3", "10732.700 m3", "21845.000 m3"]'::jsonb, 1, '10123.000 m3 is the sum of each tank''s stock above its own heel. 10077.700 m3 is the farm''s stock less the farm''s heel in one step, 10732.700 m3 the stock with no heel taken off, and 21845.000 m3 the working capacity.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 5, 'The digest prints the farm''s stock less the farm''s heel as 10077.700 m3 and says it is not pumpable stock. What is wrong with it?', '["It counts IB-T2''s 164.700 m3 as pumpable, since the whole stock is netted in one step.", "It fills IB-T2''s heel shortfall with product from the other tanks.", "It takes the heel off twice, once per tank and once again for the farm.", "It leaves the heel of IB-T4 out, since kerosene is netted apart from petrol."]'::jsonb, 1, 'Netting across the farm lets IB-T2''s missing heel volume be made good from other tanks'' product. In the digest''s words, "no pump lends one tank''s volume to another''s heel". Counted tank by tank the pumpable stock is 10123.000 m3.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 6, 'The IBAFO farm prints 3.8345 days of cover. Which two figures does the engine divide to get it?', '["Pumpable stock 10123.000 m3 by daily throughput 2640.000 m3.", "Stock 10732.700 m3 by daily throughput 2640.000 m3.", "Working capacity 21845.000 m3 by daily throughput 2640.000 m3.", "Pumpable stock 10123.000 m3 by the rack''s 216 trucks a day."]'::jsonb, 0, 'Days of cover = pumpable stock / daily throughput. The numerator is the tank-by-tank figure, so a cover built on the raw stock or the netted stock would count product that cannot all be lifted. The throughput is the depot''s liftings in m3, supplied by the caller.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 7, 'tankFarmCover is called on the IBAFO tanks with no daily throughput. What does it give?', '["Days of cover none, and turns a year 44.1108 from the working capacity alone.", "Days of cover worked from the rack''s count of 216 trucks a day.", "REFUSED: Throughput and the throughput fee are both needed for the money answer.", "Days of cover none and turns a year none."]'::jsonb, 3, 'Both figures divide or multiply by the daily throughput, and the engine does not infer it. With no throughput it gives none for both. The sentence about the throughput fee belongs to throughputEconomics, a different call.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 8, 'IB-T1 and IB-T2 both hold petrol. How much petrol can the pumps lift at IBAFO this morning?', '["5288.400 m3, IB-T1''s stock.", "10123.000 m3, the farm''s pumpable stock.", "5078.400 m3, IB-T1''s pumpable stock.", "3752.600 m3, IB-T3''s pumpable."]'::jsonb, 2, 'IB-T2 is below its heel and adds nothing until it is filled above it, so the liftable petrol is IB-T1''s 5078.400 m3. The farm''s pumpable stock pools petrol, gas oil and kerosene, and IB-T3 holds gas oil.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 9, 'What ullage does tankFarmCover print for IB-T3, the farm''s gas oil tank?', '["11767.300 m3", "7335.300 m3", "1097.400 m3", "3752.600 m3"]'::jsonb, 2, 'IB-T3''s row prints 1097.400 m3 of ullage, its capacity less its stock. 11767.300 m3 is the farm''s ullage summed over the tanks, 7335.300 m3 is IB-T2''s ullage and 3752.600 m3 is IB-T3''s pumpable stock.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 10, 'IB-T2 reads an ullage of 7335.300 m3 and a pumpable stock of 0.000 m3. What does that pair say?', '["The tank ready to receive is the one that cannot yet deliver.", "The tank is empty and can be taken out of the farm''s capacity.", "The farm''s ullage is overstated by the same volume.", "The tank''s stock has been counted twice."]'::jsonb, 0, 'Ullage is capacity less stock, never below zero; pumpable stock is stock above heel, never below zero. IB-T2 holds 164.700 m3, below its 210.000 m3 heel, and it has room for a receipt. It is a tank waiting for a receipt.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 11, 'IB-T2 holds 164.700 m3 in a 7500.000 m3 tank. How does its ullage of 7335.300 m3 enter the farm''s 11767.300 m3?', '["It is left out, since IB-T2 sits below its heel.", "It enters less IB-T2''s heel of 210.000 m3.", "It enters as IB-T2''s capacity less its heel.", "As IB-T2''s capacity less its stock, summed with the other tanks."]'::jsonb, 3, 'IB-T2''s row prints capacity 7500.000 m3, stock 164.700 m3 and ullage 7335.300 m3, and the digest counts the farm''s ullage as each tank''s capacity less its stock, never below zero, summed over the tanks. The heel appears in no part of that count.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 12, 'IBAFO''s days of cover of 3.8345 is pumpable stock over daily throughput. Which quantity has no place in that formula?', '["The heel of each tank, through the pumpable stock.", "A receipt due into the farm.", "The daily liftings of 2640.000 m3.", "The stock of each tank above its heel."]'::jsonb, 1, 'Days of cover = pumpable stock / daily throughput, and the daily throughput is the liftings, 2640.000 m3. Pumpable stock is each tank''s stock above its own heel, so the heel and the stock both enter it. No receipt enters the formula.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 13, 'Why can the farm''s days of cover not tell a manager how long the petrol alone will last?', '["It uses the netted stock of 10077.700 m3, which mixes products across heels.", "It is printed to four decimals, and a product cover needs a finer precision.", "It pools petrol, gas oil and kerosene against all liftings together.", "It leaves out IB-T2, which holds petrol, so petrol is understated."]'::jsonb, 2, 'The farm figure divides all three products'' pumpable stock by all liftings. A depot can run short of petrol while it still holds plenty of gas oil. A product''s cover needs that product''s tanks and that product''s liftings.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 14, 'Where does the daily throughput of 2640.000 m3 in the farm''s cover and turns come from?', '["The caller supplies it as the depot''s liftings.", "The engine works it out from the rack''s 216 trucks a day.", "The engine takes it from the farm''s working capacity.", "The engine sets it from the farm''s ullage."]'::jsonb, 0, 'The farm table labels it daily throughput (liftings), and with no daily throughput the engine gives days of cover none and turns a year none, so the engine does not infer it. The rack prints trucks a day and no volume.'),
  ('supply', 'intermediate', 'module', 'm03-the-tank-farm', 15, 'The IBAFO farm''s volumes print to three decimals of a cubic metre. How does tankFarmCover treat each tank''s stock?', '["As a gross volume it corrects to standard with the farm''s VCF.", "As a dip read through its strapping table.", "As a standard volume it converts back to gross before netting heels.", "As the depot''s recorded stock, taken as given."]'::jsonb, 3, 'The farm model does not correct a stock to standard; that is the Associate tier''s work at AKODO. Read every IBAFO volume as the depot''s recorded stock, and do not add a gross figure from one source to a standard figure from another.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 1, 'IBAFO''s invented period inputs are a throughput of 2640.000 m3 at an invented fee of 7.80 USD/m3. Which figure is the period''s revenue?', '["4988.00 USD", "20592.00 USD", "14388.00 USD", "9400.00 USD"]'::jsonb, 1, 'Revenue = throughput x fee, 20592.00 USD. 4988.00 USD is the margin after the invented variable and fixed costs, 14388.00 USD the margin with the fixed cost left blank, and 9400.00 USD the invented fixed cost itself.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 2, 'IBAFO''s invented fixed cost goes untyped for the period. Which line does throughputEconomics print?', '["margin 14388.00 USD; assumedZero: none", "margin 4988.00 USD; assumedZero: fixed cost", "REFUSED: Throughput and the throughput fee are both needed for the money answer.", "margin 14388.00 USD; assumedZero: fixed cost"]'::jsonb, 3, 'A blank cost is taken as zero and named. The margin rises to 14388.00 USD, and assumedZero says which zero the engine assumed. A margin quoted from that row without its assumedZero line is a margin with the fixed cost silently left out.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 3, 'An operator forgets to type IBAFO''s invented throughput fee. Which answer comes back?', '["REFUSED: Throughput and the throughput fee are both needed for the money answer.", "margin 4988.00 USD with the fee named in assumedZero.", "revenue none and margin none, with the carbon side computed.", "margin 14388.00 USD, since the fee is read as the fixed cost."]'::jsonb, 0, 'The money answer needs the throughput and the fee, and a blank in either is refused. Only a blank cost or loss is taken as zero and named in assumedZero.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 4, 'Which two inputs does throughputEconomics need for its money answer, refusing the call when either is blank?', '["The fee and the fixed cost, the two money inputs of the period.", "The throughput and the density, since the loss needs both.", "The throughput and the fee.", "The emission factor and the density, since carbon needs both."]'::jsonb, 2, 'The refusal names the throughput and the throughput fee. A blank cost or loss is taken as zero and named; a missing density or emission factor leaves the carbon side as none while the money side prints.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 5, 'IBAFO''s invented revenue is 20592.00 USD and its margin 4988.00 USD. What does throughputEconomics take off the revenue to reach the margin?', '["The variable cost on the throughput, and nothing else.", "The variable cost on the throughput and the fixed cost.", "The fixed cost of 9400.00 USD, and nothing else.", "The fixed cost and the period''s loss priced at the fee."]'::jsonb, 1, 'Margin = revenue - throughput x variable cost - fixed cost, with the invented variable cost of 2.35 USD/m3 and fixed cost of 9400.00 USD. With the fixed cost blank the margin reads 14388.00 USD. The margin formula has no loss in it; the loss is weighed in tonnes for the carbon side.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 6, 'IBAFO''s period loss of petrol, at a density of 745.2 kg/m3, weighs 3.4279 tonnes. Why is there a division by 1000?', '["It converts m3 to litres.", "It turns the density into a VCF.", "It spreads the loss over a thousand m3 of throughput.", "It turns kilograms into tonnes."]'::jsonb, 3, 'Loss tonnes = loss m3 x density / 1000. Cubic metres times kilograms per cubic metre gives kilograms, and the division turns them into tonnes. Nothing else enters.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 7, 'Density is missing from the IBAFO period. Which note explains the gap in the carbon columns?', '["No emission factor supplied, so the carbon side is not computed. Factors are published, versioned data; an invented one would be worse than none.", "No diesel emission factor supplied, so the carbon figure is absent rather than zero.", "No product density supplied, so the loss has no weight and the carbon side is not computed.", "REFUSED: Density is required to convert between mass and volume; it is not assumed."]'::jsonb, 2, 'throughputEconomics does not refuse the call; it prints the money side and names why the carbon side is missing. The refusal about mass and volume belongs to cargoQuantities, and the diesel note to the truck lane.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 8, 'With the density blank, which IBAFO figures read none?', '["Loss tonnes, emissions and the intensity.", "Emissions and the intensity only; loss tonnes still print 3.4279.", "Margin, loss tonnes and emissions, since the call is incomplete.", "Revenue and margin."]'::jsonb, 0, 'With no density the loss has no weight, so every figure built on it reads none: loss tonnes, emissions and kg CO2e per tonne of throughput. The money columns still print 20592.00 USD and 4988.00 USD.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 9, 'The IBAFO call is run with no emission factor and the density typed. What does loss tonnes read?', '["none", "1.481061", "2913.7320", "3.4279"]'::jsonb, 3, 'Without a factor the loss still has a weight, 3.4279 tonnes; only the emissions and the intensity read none. 1.481061 is the intensity per tonne of throughput and 2913.7320 the emissions in kg CO2e with the synthetic factor.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 10, 'What is the 850 kg CO2e a tonne factor used in the IBAFO carbon ledger?', '["The engine''s shipped default for petrol.", "A synthetic factor invented for the course.", "A published factor for petrol, quoted here for the arithmetic.", "The PRODUCT_REFERENCE value the engine reads when none is typed."]'::jsonb, 1, 'The engine ships no emission factor. The digest labels 850 kg CO2e a tonne SYNTHETIC, invented for this course and not a published figure. It exists only to show the arithmetic.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 11, 'With the synthetic 850 kg CO2e a tonne factor, IBAFO prints 1.481061 kg CO2e per tonne of throughput. What is that figure?', '["The emissions spread over the period''s throughput weighed in tonnes.", "The emissions spread over the loss tonnes of 3.4279.", "The emissions spread over the throughput in m3.", "The emissions spread over the margin in US dollars."]'::jsonb, 0, 'It is an intensity: 2913.7320 kg CO2e over the period''s throughput in tonnes, so a period can be compared with another at a different volume. It inherits the synthetic factor and is quoted only with the factor beside it.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 12, 'Why does the engine ship no emission factor?', '["Emissions are the Economics courses'' ledger, which the depot engine leaves alone.", "A factor needs the density first, and the density is never typed.", "Factors are published, versioned data; an invented one would be worse than none.", "The throughput fee already carries the cost of carbon in its rate."]'::jsonb, 2, 'The engine''s own note gives the reason: "Factors are published, versioned data; an invented one would be worse than none." The engine computes emissions from a factor the caller supplies, and IBAFO types its density, 745.2 kg/m3.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 13, 'Between the IBAFO case with factor and density supplied and the case with no density, which column changes?', '["Margin, from 4988.00 USD to none.", "Revenue, from 20592.00 USD to none.", "Margin per m3, from 1.89 USD to none, as the loss is not weighed.", "Loss tonnes, from 3.4279 to none."]'::jsonb, 3, 'The money columns are identical in all three cases, because revenue and margin need the throughput, the fee and the costs, and none needs a density. The carbon columns fail from the first link that has no input onward.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 14, 'A report stretches IBAFO''s margin of 4988.00 USD into a value for the depot. What is the margin, by the engine''s formula?', '["Revenue less costs for one period, with no discounting in it.", "A valuation once the invented fixed cost is spread over the depot''s life.", "A present value, since the fee is paid within the period.", "The depot''s IRR once divided by the throughput."]'::jsonb, 0, 'Margin = revenue - throughput x variable cost - fixed cost, and the fixed cost is for the period. Nothing in the formula discounts, and no rate of return is formed; this course computes no NPV or IRR.'),
  ('supply', 'intermediate', 'module', 'm04-throughput-economics', 15, 'The pricing module''s PRODUCT_REFERENCE lists a typical petrol density. With the density box blank, does throughputEconomics use it?', '["Yes. It weighs the loss at the typical density and names it in assumedZero.", "No. The loss gets no weight.", "Yes. It weighs the loss at the typical density, as the loss rows print.", "No. It refuses the whole call until a density is typed."]'::jsonb, 1, 'Nothing in the module reads PRODUCT_REFERENCE unless a caller passes a figure in. IBAFO''s typed density is 745.2 kg/m3, from the product actually lost. With the box blank the engine gives the loss no weight and still prints the margin.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 1, 'The IBAFO lane''s cycle is round trip / average speed + load + discharge + queue hours, 18.065 hours. Which terms of that cycle are typed as hours?', '["The round trip and the average speed.", "The working hours a day and working days a year.", "The load, discharge and queueing hours.", "The queueing hours alone, taken from the rack''s mean wait."]'::jsonb, 2, 'The lane types 1.5 h to load, 1.25 h to discharge and 1.75 h queueing. The round trip is 624.00 km and the speed 46 km/h, so that term is the driving time. The 12 working hours and 300 days are outside the cycle. The 1.75 h queueing is the lane''s own typed figure, and the rack''s mean wait is 47.2652 minutes.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 2, 'On its invented costs, the IBAFO lane moves from 312.00 km to 468.00 km. Which printed pair describes the change?', '["Cost per litre delivered from 15.0704 naira to 20.6072.", "Cycle hours from 18.065 to 11.283.", "Trips a truck a day from 0.664260 to 1.063584.", "Cost a trip from 495830.99 naira to 313665.50."]'::jsonb, 0, 'At 468.00 km the engine prints 24.848 cycle hours, 0.482940 trips a truck a day and 20.6072 naira a litre delivered, on invented costs. The 11.283 hours, 1.063584 trips and 313665.50 naira are the 156.00 km row.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 3, 'Across the three distances of the IBAFO lane, which invented cost line prints a different figure at each distance?', '["Driver", "Tolls and levies", "Overhead", "Truck depreciation"]'::jsonb, 3, 'Driver, Tolls and levies and Overhead print the same invented figure at 156.00, 312.00 and 468.00 km. Diesel, Maintenance and tyres and Truck depreciation move. Depreciation is the truck''s capital spread over the trips a year, and a longer cycle allows fewer of them.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 4, 'The IBAFO lane''s invented cost a trip is 495830.99 naira. Which litres does the engine spread it over to print 15.0704 naira a litre?', '["33000.00 litres, the payload loaded at the rack.", "32901.00 litres delivered after the transit loss.", "28125.00 litres, the station''s ullage at reorder.", "11393.64 litres, the fleet''s spare litres a day."]'::jsonb, 1, 'Cost per litre delivered = cost per trip / the litres delivered after the transit loss: 32901.00 litres from a 33000.00 litre payload at a transit loss of 0.3 percent. 28125.00 litres is the station''s ullage at reorder and 11393.64 litres the fleet''s spare litres a day.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 5, 'The IBAFO lane reports 224.64 diesel litres a trip. What does it print for kg CO2e a trip?', '["0, since a missing factor is read as a zero emission.", "A figure from the synthetic 850 kg CO2e a tonne factor.", "none, with a note that no diesel emission factor was supplied.", "A refusal, with the lane left uncosted until a factor is typed."]'::jsonb, 2, 'The engine ships no factor, so the diesel volume is computed and its emissions wait for a factor with a source. In the engine''s words the carbon figure "is absent rather than zero". The rest of the lane still prints complete true.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 6, 'The IBAFO lane is run with the invented driver cost box left blank. What does the engine print?', '["complete true, missing none, 13.3075 naira a litre delivered.", "complete true, missing none, 15.0704 naira a litre delivered.", "complete false, missing Driver, 13.2401 naira a litre delivered.", "complete false, missing Driver, 13.3075 naira a litre delivered."]'::jsonb, 3, 'A blank cost box is a missing cost and is named. The cost a trip drops to 437830.99 naira and the answer is flagged incomplete. 13.2401 naira is the floor with no truck capital cost, and 15.0704 naira is the lane with every cost typed.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 7, 'The IBAFO lane is run with the driver cost left out of the call entirely. Why does it read complete true at 13.3075 naira a litre?', '["The engine fills the typical invented driver cost of 58000.00 naira.", "driverCostPerTrip defaults to 0 in the engine''s signature.", "A cost left out is named in assumedZero, which counts as complete.", "The driver is paid from the Overhead line of 37500.00 naira."]'::jsonb, 1, 'An absent input takes the default the signature states, so the row reads the same 437830.99 naira a trip as the blank row with no missing input. A form that drops an empty field before calling the engine turns a missing driver cost into a complete answer.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 8, 'With no truck capital cost, the IBAFO lane prints 13.2401 naira a litre delivered. What is that figure?', '["A floor: the lane costs at least this, with Truck depreciation missing.", "The lane''s full cost, with the capital typed as a zero and complete true.", "The cost per litre on the loaded payload of 33000.00 litres.", "The cost at 156.00 km, the shortest distance swept."]'::jsonb, 0, 'The engine prints complete false and names Truck depreciation as missing. A floor is a lower bound: the true cost per litre is that figure plus whatever the missing line would add, so it cannot be quoted as the lane''s cost.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 9, 'The IBAFO stations take 1260000.00 litres a day on a 33000.00 litre payload. Why does fleetSizing print 58 trucks?', '["It rounds 38.181818 trips needed to the nearest whole truck.", "It adds a spare truck for breakdowns to the fleet it computes.", "It takes the ceiling of trips needed over trips a truck a day.", "It divides the demand by the 32901.00 litres delivered a trip."]'::jsonb, 2, 'Trips needed = demand / payload = 38.181818 a day; trucks = the ceiling of 38.181818 / 0.664260. A fleet one truck short fails the demand every day. The engine adds no allowance for breakdowns.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 10, 'The 58 IBAFO trucks can make 38.527080 trips a day against 38.181818 needed. What is the spare of 0.345262 trips, or 11393.64 litres, a day?', '["A reserve the engine adds for breakdowns and peaks.", "The trips lost to the lane''s 0.3 percent transit loss.", "The share of the fleet held back for the forecourt peak.", "What the ceiling bought."]'::jsonb, 3, 'The spare is what rounding up to a whole truck buys, and the engine prints it in trips and in litres. The engine sizes for the average cycle, and any spare for breakdowns or peaks is a decision the operator adds.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 11, 'On the IBAFO lane the demand rises from 1260000.00 to 1980000.00 litres a day. Which printed pair describes the change?', '["Trucks required from 58 to 91.", "Trucks required from 31 to 58.", "Trips needed from 38.181818 to 20.000000.", "Fleet utilisation from 0.940897 to 0.992594."]'::jsonb, 0, 'The demand sweep prints 60.000000 trips needed, 91 trucks and a fleet utilisation of 0.992594 at 1980000.00 litres a day. 31 trucks and 20.000000 trips belong to the 660000.00 litre row, and 0.940897 to the 330000.00 litre row.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 12, 'Nobody types the demand for the IBAFO fleet. Which answer does fleetSizing return?', '["REFUSED: Distance, payload and average speed are required and must be positive.", "REFUSED: Demand, payload and trips per truck per day are required and must be positive.", "REFUSED: Throughput, litres per transaction, dispense rate and nozzle count are required.", "Zero trucks required, with a fleet utilisation of none."]'::jsonb, 1, 'A fleet sized for no demand is no fleet, and the trips a truck a day must come from a lane. The sentence about distance and speed is truckingEconomics'' refusal and the one about nozzles is stationSizing''s.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 13, 'stationSizing sizes the IBAFO forecourt with rackQueue. Which station figure stands in for the rack''s load minutes?', '["Peak transactions an hour, 135.00.", "Transactions a day, 1125.0.", "Forecourt mean wait, 2.2083 minutes.", "Service minutes, 2.342."]'::jsonb, 3, 'Service minutes = litres a transaction / dispense rate + an overhead, the time a car holds a nozzle. The peak transactions an hour are the arrivals and the nozzles are the bays. The queue is sized on the peak hour, which carries a share of 0.12 of the day''s transactions.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 14, 'The nozzle sweep is read at the IBAFO forecourt''s peak. What does it print for 5 nozzles?', '["Stable true, probability of waiting 0.688546, mean wait 2.2083 minutes.", "Stable false, probability of waiting 1.053947, the same as its utilisation.", "Stable false, probability of waiting 1.000000, mean wait none.", "Stable true, probability of waiting 0.392371, mean wait 0.5311 minutes."]'::jsonb, 2, 'At 5 nozzles the utilisation is 1.053947, the forecourt cannot keep up with its peak, and the engine prints no wait, as it did for the rack at 3 bays. The smallest stable forecourt in the sweep has 6 nozzles.'),
  ('supply', 'intermediate', 'module', 'm05-the-lane-the-fleet-and-the-station', 15, 'The IBAFO station reorders at 0.25 of usable, leaving 28125.00 litres of ullage. Of the fractions swept, which one lets the 33000.00 litre delivery fit?', '["0.1, with 33750.00 litres of ullage at reorder.", "0.15, with 31875.00 litres of ullage at reorder.", "0.2, with 30000.00 litres of ullage at reorder.", "0.25, once the transit loss brings the load to 32901.00 litres."]'::jsonb, 0, 'Ullage at reorder = capacity less the reorder level, and only 0.1 leaves room for a full load. The engine checks the payload loaded, so the lane''s 32901.00 litres delivered does not enter the check.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'fleetSizing prints 58 IBAFO trucks. Where does its trips a truck a day of 0.664260 come from?', '["The rack''s 216 trucks a day.", "The IBAFO lane, from its cycle of 18.065 hours.", "The farm''s 44.1108 turns a year, spread over 365 days.", "fleetSizing works it out from the demand and the payload."]'::jsonb, 1, 'The fleet table labels 0.664260 trips a truck a day (from the lane), and on the lane trips a truck a day = working hours / cycle, with 12 working hours and a cycle of 18.065 hours. fleetSizing refuses without it: "Demand, payload and trips per truck per day are required and must be positive." Demand over payload gives the trips needed, 38.181818.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'A manager plans for traffic growth on IBAFO''s 4 bays. What do the printed rows say lies one step past 9.5 arrivals an hour?', '["At 10 arrivals the wait reaches 245.7297 minutes.", "At 10 arrivals the rack is stable at a utilisation of 1.000000.", "At 10 arrivals the rack keeps up once a fifth bay is typed.", "At 10 arrivals no average wait exists."]'::jsonb, 3, 'At 9.5 arrivals the mean wait is 106.9703 minutes. At 10 the engine refuses: the rack cannot keep up and the queue grows without limit. 245.7297 minutes belongs to the load minutes sweep at 26 minutes a load.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'The IBAFO morning report sets the farm''s pumpable stock of 10123.000 m3 beside its daily liftings of 2640.000 m3. Which printed figure is the first over the second?', '["Days of cover, 3.8345.", "The turns a year, 44.1108.", "Fleet utilisation, 0.991038.", "The rack''s utilisation, 0.900000."]'::jsonb, 0, 'Days of cover = pumpable stock / daily throughput, and the farm table prints 3.8345. Turns a year divide the daily throughput x 365 by the working capacity, 44.1108. The two utilisations belong to the fleet and the rack.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Which IBAFO figure joins the rack''s queue to the farm''s cover?', '["The rack''s 216 trucks a day, which the farm divides into its days of cover.", "The daily throughput of 2640.000 m3, which the rack reads as its arrivals.", "None: they are separate engine calls with separate limits.", "The mean queue of 7.0898 trucks, which the farm reads as its liftings."]'::jsonb, 2, 'The rack limits how fast product can leave; the farm limits how long there is product to send and how much room there is for the next receipt. The engine prints no figure that joins them, so a report keeps them in separate tables with their own units.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'The IBAFO lane prints complete true on its invented costs. What does that flag rest on?', '["The diesel emission factor was supplied.", "No cost box was left blank.", "The payload fits.", "The fleet is sized."]'::jsonb, 1, 'complete true says no cost is missing. A blank or null cost box reads complete false with the cost named, and a cost left out of the call takes the default the signature states and still reads complete true. The carbon figure reads none because no diesel emission factor was supplied, and complete stays true. The payload check is the station''s and the fleet is fleetSizing''s.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'On the lane, which printed figure feeds the trips a truck a day, the depreciation a trip and the fleet together?', '["The litres delivered a trip, 32901.00.", "The payload of 33000.00 litres.", "The Diesel line, 278553.60 naira a trip.", "The cycle, 18.065 hours."]'::jsonb, 3, 'Trips a truck a day = working hours / cycle, the truck''s capital is spread over the trips a year that cycle allows, and fleetSizing takes the lane''s trips a truck a day. The payload sets the trips needed and the litres delivered set the cost per litre; the Diesel line is one cost a trip.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'The IBAFO fleet of 58 runs at a fleet utilisation of 0.991038. What does that say about breakdowns?', '["Nothing: the engine sizes for the average cycle and the operator adds any spare.", "The 0.345262 spare trips a day are the engine''s reserve for breakdowns.", "The ceiling adds one truck for breakdowns before it reports 58.", "At 0.991038 the fleet is unstable, as a rack is above one."]'::jsonb, 0, 'A fleet utilisation is a figure for an average day. The spare of 0.345262 trips and 11393.64 litres a day is what the ceiling bought. A truck in the workshop changes what the fleet can make, and the engine prints no allowance for it.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'At one IBAFO forecourt with 6 nozzles, which utilisation, probability of waiting and mean wait does stationSizing print, in that order?', '["0.900000, 0.787753 and 47.2652 minutes.", "0.878289, 1.000000 and none.", "0.878289, 0.688546 and 2.2083 minutes.", "1.053947, 1.000000 and none."]'::jsonb, 2, 'The forecourt table prints a utilisation of 0.878289, a probability of waiting of 0.688546 and a mean wait of 2.2083 minutes at 6 nozzles, stable true. 0.900000, 0.787753 and 47.2652 minutes are the rack at 4 bays, and 1.053947 with no mean wait is the forecourt at 5 nozzles, stable false.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'The IBAFO lane''s payload reappears at the station. What does stationSizing check it against, and with which volume?', '["The ullage at reorder, with the 32901.00 litres delivered after the transit loss.", "The usable tank litres, with the 33000.00 litres loaded.", "The dead stock, with the 32901.00 litres delivered.", "The ullage at reorder, with the 33000.00 litres loaded."]'::jsonb, 3, 'stationSizing checks the payload loaded against the 28125.00 litres of ullage at the reorder level and warns that a 33000 litre load cannot discharge into it. The lane delivers 32901.00 litres a trip after its transit loss, and the station''s check does not use that figure.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Along the IBAFO chain, what does a blank box give at each link?', '["A typical figure the engine keeps for the link, named in a note.", "A refusal, a none or a named gap, and never a silent zero.", "A zero at every link, with the answer marked complete.", "A refusal at the first link, and nothing printed after it."]'::jsonb, 1, 'A missing demand or nozzle count is refused. A farm with no daily throughput reads days of cover none. A blank fixed cost is taken as zero and named in assumedZero, a blank driver cost reads complete false with Driver named, and a blank truck capital cost reads a floor with Truck depreciation named.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'The morning report asks which IBAFO tank is below its heel. Which row answers it?', '["IB-T2, 164.700 m3 against a heel of 210.000 m3.", "IB-T4, 1377.000 m3 against a heel of 85.000 m3.", "IB-T3, 3902.600 m3 against a heel of 150.000 m3.", "IB-T1, 5288.400 m3 against a heel of 210.000 m3."]'::jsonb, 0, 'IB-T2''s stock of 164.700 m3 is under its heel of 210.000 m3, and its pumpable stock prints 0.000 m3. The other three tanks hold more than their heels and print a pumpable stock above zero: IB-T1 5078.400 m3, IB-T3 3752.600 m3 and IB-T4 1292.000 m3.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'The Expert tier converts one cargo between tonnes, cubic metres, litres and barrels. Which input can a conversion between mass and volume not proceed without?', '["A VCF.", "An exchange rate.", "A density.", "A freight rate."]'::jsonb, 2, 'The conversion between mass and volume needs a density the engine never assumes. The same rule held in this tier: a loss with no density has no weight, and the carbon side is not computed.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Why is every freight, duty, levy and exchange rate in the Expert tier labelled invented?', '["Rates are hidden from learners.", "The rates are published and current, and are rounded for teaching.", "Only large rates are invented.", "The engine ships no rate by design."]'::jsonb, 3, 'RATE_DISCLAIMER calls every rate a required input, and each line of IMPORT_TEMPLATE and PUMP_TEMPLATE ships its rate as none. The course invents each rate it uses, as it invented the throughput fee and the lane''s costs in this tier.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'On the lane a transit loss spread the trip''s cost over fewer litres. Where does the Expert tier meet the same effect?', '["On a whole cargo at sea: the importer pays for what was loaded and sells what arrives.", "At the forecourt, where the reorder level leaves too little ullage.", "At the rack, where a queue lowers the trucks loaded each day.", "In the tank farm, where a heel holds stock back from the pumps."]'::jsonb, 0, 'The lane''s 33000.00 litre payload delivers 32901.00 litres after the transit loss, and the cost is spread over what arrives. The next tier meets that effect on a cargo, and says the losses divide.'),
  ('supply', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Which habit from this tier does the Expert tier rely on when an incomplete build-up is labelled by the engine?', '["Reading a floor as the cost once the missing lines are set to zero.", "Reading a floor as a lower bound with its missing lines named.", "Reading an incomplete build-up as refused, with nothing printed.", "Reading a floor as a typical cost the engine fills in."]'::jsonb, 1, 'In this tier the lane with no truck capital cost printed 13.2401 naira a litre with Truck depreciation named as missing, which is a floor. The Expert tier''s engine labels an incomplete build-up as a floor in its own words, and it is read the same way.'),
  ('supply', 'intermediate', 'final', null, 1, 'A consultant quotes IBAFO''s 3.6000 erlangs and says the rack needs 3.6000 bays. What is the flaw?', '["Offered load is already divided by the bays, so 3.6000 is a utilisation.", "Offered load counts trucks a day, so it must first be divided by the 216 trucks.", "Offered load is traffic; bays come whole and the engine refuses a fraction.", "Nothing: the engine rounds 3.6000 bays to 4 and runs the rack."]'::jsonb, 2, 'Offered load = arrivals per hour / (60 / load minutes), and the bay count is not in it; utilisation = offered load / bays. The bay count must be a whole number: 2.5 bays is refused with "The number of bays must be a whole number, one or more." The engine does not round it.'),
  ('supply', 'intermediate', 'final', null, 2, 'Read the load minutes sweep at 26 minutes a load on IBAFO''s 4 bays. Which set of figures does it print?', '["Utilisation 0.975000, probability of waiting 0.945114, mean wait 245.7297 minutes.", "Utilisation 0.950000, probability of waiting 0.891419, mean wait 106.9703 minutes.", "Utilisation 0.975000, probability of waiting 0.300939, mean wait 245.7297 minutes.", "Utilisation 1.000000, probability of waiting 1.000000, mean wait none."]'::jsonb, 0, 'At 26 minutes the engine prints 0.975000, 0.945114 and 245.7297 minutes. The 0.300939 at that row is the Erlang B the digest derives from the Erlang C. The 0.950000 row is 9.5 arrivals in the arrivals sweep.'),
  ('supply', 'intermediate', 'final', null, 3, 'At 16 minute loads the digest prints a probability of waiting of 0.287043 and an Erlang B of 0.138706 worked out from it. Which one is the chance an arriving truck queues?', '["0.138706, the blocking figure.", "0.287043, the Erlang C.", "Both: they describe one rack.", "Neither: the rack is unstable."]'::jsonb, 1, 'The engine reports Erlang C as the probability of waiting. Erlang B is the probability every bay is busy in a rack with no queue, where the truck leaves, and the digest derives it from the engine''s Erlang C.'),
  ('supply', 'intermediate', 'final', null, 4, 'The IBAFO rack''s mean wait is 47.2652 minutes and the digest works out 60.0000 minutes from the engine''s figures. Which statement is true?', '["47.2652 averages the trucks that queue; 60.0000 averages every truck.", "47.2652 averages every truck; 60.0000 averages the trucks that queue.", "60.0000 is the mean wait plus the 24 minute load, the time on site.", "60.0000 is the wait at 5 bays, 47.2652 the wait at 4."]'::jsonb, 1, 'The engine''s figure takes in the trucks that load at once. The digest divides it by the probability of waiting to reach the trucks that queue. 7.0353 minutes is the 5 bay rack, and the time on site is a separate row of the rack table.'),
  ('supply', 'intermediate', 'final', null, 5, 'In the bay sweep at 9 arrivals an hour, the 6 bay row prints a mean wait of 1.9657 minutes. Which mean queue sits beside it?', '["1.0553 trucks", "0.0913 trucks", "0.2948 trucks", "0.196566 trucks"]'::jsonb, 2, 'The 6 bay row prints 0.2948 trucks. 1.0553 is the 5 bay row, 0.0913 the 7 bay row, and 0.196566 is the 6 bay probability of waiting, a probability with no unit of trucks.'),
  ('supply', 'intermediate', 'final', null, 6, 'A call to rackQueue carries 9 arrivals an hour and 4 bays and no load time at all. What comes back?', '["The refusal asking for both the arrival rate and the load time.", "The whole number sentence, since the bays cannot be loaded without a load time.", "The rack cannot keep up, since a service rate of none gives no spare capacity.", "A run at a typical 24 minute load, named as assumed in the engine''s note."]'::jsonb, 0, 'The refusal table prints "Arrival rate and load time are both needed." for a load time of none and for 0. The engine does not borrow a typical depot''s load time.'),
  ('supply', 'intermediate', 'final', null, 7, 'With only 3 bays against IBAFO''s traffic, the mean queue column reads none. Why?', '["The mean queue at 3 bays is zero, and the engine prints a zero as none.", "No truck queues when all 3 bays are loading.", "Its Erlang B cannot be derived above one, so no queue can follow.", "A queue that grows without limit has no average length."]'::jsonb, 3, 'At 3 bays the utilisation is 1.200000, the rack is stable false and the probability of waiting is 1.000000, so every arriving truck waits. The engine prints none for both the mean wait and the mean queue, and where it states the reason it says the queue grows without limit.'),
  ('supply', 'intermediate', 'final', null, 8, 'Between the 7 and 8 arrivals rows of the arrivals sweep, how does the chance of queueing move?', '["From 0.700000 to 0.800000.", "From 0.428654 to 0.596432.", "From 0.596432 to 0.787753.", "From 0.287043 to 0.428654."]'::jsonb, 1, 'The arrivals sweep prints 0.428654 at 7 arrivals and 0.596432 at 8. 0.700000 and 0.800000 are the utilisations of those rows; the other pairs are the steps from 8 to 9 and from 6 to 7.'),
  ('supply', 'intermediate', 'final', null, 9, 'How does tankFarmCover count the IBAFO farm''s ullage?', '["The farm''s capacity less the farm''s stock, taken in one step for the farm.", "The farm''s working capacity less the pumpable stock, heel left out.", "Each tank''s capacity less its stock, never below zero, summed.", "Each tank''s capacity less its heel, summed over the tanks."]'::jsonb, 2, 'Ullage is counted the same way as pumpable stock, tank by tank: each tank''s capacity less its stock, never below zero, summed over the tanks, 11767.300 m3. The heel is not in the ullage formula; it enters working capacity and pumpable stock.'),
  ('supply', 'intermediate', 'final', null, 10, 'Read IB-T1''s row: 5288.400 m3 in the tank above a 210.000 m3 heel. Which pumpable figure sits in it?', '["5078.400 m3", "5288.400 m3", "2211.600 m3", "7500.000 m3"]'::jsonb, 0, 'Pumpable stock is stock above the tank''s own heel: 5078.400 m3. 2211.600 m3 is IB-T1''s ullage. 7500.000 m3 is its capacity.'),
  ('supply', 'intermediate', 'final', null, 11, 'The IBAFO farm turns 44.1108 times a year. Which formula does the engine use?', '["Pumpable stock x 365 / daily throughput, a cover in days.", "Daily throughput x 365 / capacity, heel included.", "Daily throughput x 365 / pumpable stock.", "Daily throughput x 365 / working capacity."]'::jsonb, 3, 'Turns a year = daily throughput x 365 / working capacity, 2640.000 m3 a day over 21845.000 m3, which is capacity less heel. Pumpable stock over daily throughput is the days of cover, 3.8345.'),
  ('supply', 'intermediate', 'final', null, 12, 'On this IBAFO morning, which tank decides that the netted and tank-by-tank stock figures part company?', '["IB-T1, the petrol tank in use.", "IB-T3, the gas oil tank.", "IB-T4, the kerosene tank.", "IB-T2, below its heel."]'::jsonb, 3, 'The tank-by-tank count gives IB-T2 0.000 m3, since it holds 164.700 m3 against its 210.000 m3 heel. The netted farm figure charges IB-T2''s heel against the product in the other three tanks, which the digest rules out: no pump lends one tank''s volume to another''s heel.'),
  ('supply', 'intermediate', 'final', null, 13, 'The IBAFO farm prints a working capacity of 21845.000 m3. What does the engine take off the capacity of 22500.000 m3 to reach it?', '["The farm''s ullage, 11767.300 m3.", "The farm''s stock, 10732.700 m3.", "The farm''s heel, 655.000 m3.", "IB-T2''s heel alone, 210.000 m3."]'::jsonb, 2, 'The digest defines working capacity as capacity less heel, and the farm rows read 22500.000 m3, 655.000 m3 and 21845.000 m3. 11767.300 m3 is the ullage and 10732.700 m3 the stock; 210.000 m3 is one tank''s heel.'),
  ('supply', 'intermediate', 'final', null, 14, 'IBAFO''s invented costs are 2.35 USD/m3 variable and 9400.00 USD fixed. Which margin does the engine print with both typed?', '["4988.00 USD", "14388.00 USD", "20592.00 USD", "1.89 USD"]'::jsonb, 0, 'The margin takes both invented costs off the revenue, and with both typed assumedZero reads none and the margin 4988.00 USD. Leaving the fixed cost blank lifts it to 14388.00 USD; the other two options are the revenue and a per m3 column.'),
  ('supply', 'intermediate', 'final', null, 15, 'What does assumedZero report on a throughputEconomics answer?', '["Which carbon figure was left as none.", "Which input was refused.", "Which rate was invented.", "Which blank cost or loss was taken as zero."]'::jsonb, 3, 'A blank cost or loss is taken as zero and named. With nothing blank it reads assumedZero: none; with the fixed cost blank it reads assumedZero: fixed cost and a margin of 14388.00 USD.'),
  ('supply', 'intermediate', 'final', null, 16, 'Using the course''s synthetic factor of 850 kg CO2e a tonne, what emissions does the IBAFO period''s loss produce?', '["1.481061 kg CO2e per tonne", "2913.7320 kg CO2e", "3.4279 tonnes of CO2e", "none"]'::jsonb, 1, 'The synthetic 850 kg CO2e a tonne multiplies the loss tonnes, and the case with factor and density supplied prints the product as 2913.7320 kg CO2e. The other two numbers are a weight and an intensity.'),
  ('supply', 'intermediate', 'final', null, 17, 'The carbon columns of the IBAFO cases fail in a chain. With no density, where does the first none fall?', '["At loss tonnes, and every carbon figure after it.", "At emissions, with loss tonnes still at 3.4279 tonnes.", "At revenue, since the money needs a weight.", "At the intensity alone."]'::jsonb, 0, 'Each none sits at the first link with no input and at every link after it. Without a density the loss has no weight, so loss tonnes, emissions and the intensity all read none; without a factor the first none is the emissions.'),
  ('supply', 'intermediate', 'final', null, 18, 'The IBAFO period prints three carbon cases: factor and density supplied, no emission factor, and no density. Which of them print a margin of 4988.00 USD?', '["Only the case with the factor and the density supplied.", "The two cases with a density, since the loss is priced.", "All three cases, whatever the carbon side reads.", "None of them, since the margin waits on the carbon side."]'::jsonb, 2, 'The digest prints revenue 20592.00 USD and margin 4988.00 USD in all three rows. The margin is revenue less the variable and fixed costs; a missing factor or density leaves the carbon columns none and moves no money figure.'),
  ('supply', 'intermediate', 'final', null, 19, 'On the IBAFO lane, why is trips a truck a day 0.664260, below one?', '["The engine rounds each trip down to the part a driver can finish.", "The transit loss removes a share of every trip.", "The queue hours are counted twice.", "The cycle of 18.065 hours is longer than the 12 hour working day."]'::jsonb, 3, 'Trips a truck a day = working hours / cycle. A cycle longer than the working day gives a figure below one: a trip spans more than one working day, and the engine does not round it.'),
  ('supply', 'intermediate', 'final', null, 20, 'On the IBAFO lane at 156.00 km, what are the cycle hours and trips a truck a day?', '["18.065 hours and 0.664260 trips, the 312.00 km row.", "11.283 hours and 1.063584 trips.", "24.848 hours and 0.482940 trips.", "11.283 hours and 0.482940 trips."]'::jsonb, 1, 'The distance sweep prints 11.283 hours and 1.063584 trips at 156.00 km. Only the driving time changes between rows; the load, discharge and queue hours are the same in each.'),
  ('supply', 'intermediate', 'final', null, 21, 'Which invented cost line of the IBAFO lane is spread over the 199.2780 trips a truck a year?', '["Driver, 58000.00 naira a trip.", "Overhead, 37500.00 naira a trip.", "Truck depreciation, 60217.39 naira a trip.", "Diesel, 278553.60 naira a trip."]'::jsonb, 2, 'Truck depreciation is the truck''s capital spread over the trips a year the cycle allows, so a lane allowing fewer trips loads more capital onto each. At 468.00 km it prints 82826.09 naira a trip.'),
  ('supply', 'intermediate', 'final', null, 22, 'A null arrives in the driver cost field of the IBAFO lane, whose costs are invented. What reads out?', '["complete false, missing Driver, 437830.99 naira a trip.", "complete true, missing none, 437830.99 naira a trip.", "complete true, missing none, 495830.99 naira a trip.", "REFUSED: Distance, payload and average speed are required and must be positive."]'::jsonb, 0, 'The null row reads the same as the blank row: complete false with Driver named. Only a driver cost left out of the call reads complete true, because driverCostPerTrip defaults to 0 in the signature.'),
  ('supply', 'intermediate', 'final', null, 23, 'At 330000.00 litres a day on the IBAFO lane, what does fleetSizing print?', '["10.000000 trips needed, 31 trucks, fleet utilisation 0.991038.", "20.000000 trips needed, 31 trucks, fleet utilisation 0.971248.", "10.000000 trips needed, 16 trucks, fleet utilisation 0.992594.", "10.000000 trips needed, 16 trucks, fleet utilisation 0.940897."]'::jsonb, 3, 'The first row of the demand sweep, 330000.00 litres a day, needs 10.000000 trips, which 16 trucks cover at a fleet utilisation of 0.940897. The other utilisations and 31 trucks belong to larger demands.'),
  ('supply', 'intermediate', 'final', null, 24, 'The IBAFO forecourt sells 36000.00 litres a day at 32 litres a transaction with a peak share of 0.12. Which figures does stationSizing print?', '["1125.0 transactions a day and 2.342 at the peak hour.", "1125.0 transactions a day and 135.00 at the peak hour.", "135.00 transactions a day and 1125.0 at the peak hour.", "36000.00 transactions a day and 135.00 at the peak hour."]'::jsonb, 1, 'Transactions a day = throughput / litres a transaction, 1125.0; the peak hour carries its share of them, 135.00. The queue is sized for the peak, and 2.342 is the service minutes a transaction.'),
  ('supply', 'intermediate', 'final', null, 25, 'Fed the station''s printed 135.00 and 2.342, rackQueue answers 0.688454. The station prints 0.688546. Which should a report quote?', '["0.688454, the rack model''s own answer.", "Their mean, as the two roundings straddle it.", "0.688546, the station''s own figure.", "Neither, since the two models disagree."]'::jsonb, 2, 'The station and rackQueue agree when rackQueue is given the station''s unrounded arrivals and service minutes. The station reports those inputs rounded, so feeding back the printed roundings moves the answer.'),
  ('supply', 'intermediate', 'final', null, 26, 'At 7 nozzles the IBAFO forecourt prints what?', '["Utilisation 0.752820, probability of waiting 0.392371, mean wait 0.5311 minutes.", "Utilisation 0.658717, probability of waiting 0.209905, mean wait 0.1801 minutes.", "Utilisation 0.878289, probability of waiting 0.688546, mean wait 2.2083 minutes.", "Utilisation 0.752820, probability of waiting 0.086243, mean wait 0.6088 minutes."]'::jsonb, 0, 'The nozzle sweep prints 0.752820, 0.392371 and 0.5311 minutes at 7. 0.086243 and 0.6088 are the 7 bay row of the rack, a different queue.'),
  ('supply', 'intermediate', 'final', null, 27, 'The IBAFO station tank holds 40000.00 litres with 2500.00 litres of dead stock. What are its usable litres and reorder level at 0.25?', '["40000.00 usable, reorder at 10000.00.", "37500.00 usable, reorder at 6250.00.", "37500.00 usable, reorder at 28125.00.", "37500.00 usable, reorder at 11875.00."]'::jsonb, 3, 'Usable = capacity less dead stock, 37500.00 litres. Reorder level = dead stock + usable x the reorder fraction, 11875.00 litres, which leaves 28125.00 litres of ullage at reorder.'),
  ('supply', 'intermediate', 'final', null, 28, 'At a reorder fraction of 0.15, what does the IBAFO station print?', '["Ullage at reorder 33750.00 litres, payload fits true.", "Ullage at reorder 31875.00 litres, payload fits false.", "Ullage at reorder 31875.00 litres, payload fits true.", "Ullage at reorder 30000.00 litres, payload fits false."]'::jsonb, 1, 'At 0.15 the reorder level is 8125.00 litres and the ullage 31875.00 litres, too little for a 33000 litre load, so the warning prints. Only 0.1, with 33750.00 litres, fits.'),
  ('supply', 'intermediate', 'final', null, 29, 'The IBAFO lane types 1.75 queueing hours a cycle, and the rack prints a mean wait of 47.2652 minutes. How are the two linked in the engine?', '["The lane reads the rack''s mean wait and converts it to hours.", "They are not linked: the lane takes its own typed figure.", "The lane reads the rack''s mean time on site, wait and load together.", "The rack reads the lane''s 1.75 hours as its load time."]'::jsonb, 1, 'The lane types its own 1.75 h queueing into the cycle, and the rack''s mean wait prints 47.2652 minutes. The cycle is round trip / average speed + load + discharge + queue hours, with no rack figure in it, and the rack''s load time is 24 minutes.'),
  ('supply', 'intermediate', 'final', null, 30, 'A blank fixed cost in throughputEconomics and a blank driver cost in truckingEconomics are treated how?', '["The first is taken as zero and named in assumedZero; the second makes the answer complete false with Driver named.", "Both are refused, since every money input is required.", "Both are taken as zero silently, and both answers read complete.", "The first is refused; the second is filled with its typed default."]'::jsonb, 0, 'throughputEconomics refuses only a blank throughput or fee, and a blank cost reads margin 14388.00 USD with assumedZero: fixed cost. truckingEconomics names a blank cost as missing: complete false, 437830.99 naira a trip.'),
  ('supply', 'intermediate', 'final', null, 31, 'IBAFO prints three utilisations: the rack''s 0.900000, the forecourt''s 0.878289 and the fleet''s 0.991038. Which of them is not a queue figure?', '["The rack''s 0.900000.", "The forecourt''s 0.878289.", "The fleet''s 0.991038.", "All three are queue figures."]'::jsonb, 2, 'The rack and the forecourt are both rackQueue, with bays or nozzles, and utilisation = offered load / bays. The fleet''s trucks are the ceiling of trips needed over trips a truck a day, and fleetSizing reports the spare the ceiling buys; no queue enters it.'),
  ('supply', 'intermediate', 'final', null, 32, 'The farm''s daily throughput is 2640.000 m3 and the throughput economics period throughput is also 2640.000 m3. What does each call use it for?', '["Both calls divide pumpable stock by it to get days of cover.", "The farm divides pumpable stock by it; the economics call earns its invented fee on it.", "The farm earns the fee on it; the economics call works out turns.", "The farm reads it from the rack; the economics call reads it from the farm."]'::jsonb, 1, 'Days of cover = pumpable stock / daily throughput, 3.8345 days. Revenue = throughput x fee, 20592.00 USD at the invented 7.80 USD/m3. Both are typed inputs; neither call infers it.'),
  ('supply', 'intermediate', 'final', null, 33, 'The station''s dead stock of 2500.00 litres and IB-T3''s heel of 150.000 m3 play which common role?', '["Free water that the dip less the water height removes.", "Ullage kept empty so that the next receipt has room to discharge into the tank.", "Volume taken off the capacity before the usable or working room is counted.", "A reserve the operator holds for breakdowns."]'::jsonb, 2, 'The station''s usable litres are capacity less dead stock, 37500.00 litres, and a depot tank''s working capacity is capacity less heel. Room for a receipt is the ullage, capacity less stock, and neither figure is water or a breakdown reserve.'),
  ('supply', 'intermediate', 'final', null, 34, 'The IBAFO farm prints an ullage, and the IBAFO forecourt prints an ullage at reorder. Which pair does the digest print?', '["Farm 11767.300 m3; forecourt 28125.00 litres.", "Farm 10123.000 m3; forecourt 28125.00 litres.", "Farm 11767.300 m3; forecourt 11875.00 litres.", "Farm 21845.000 m3; forecourt 37500.00 litres."]'::jsonb, 0, 'The farm''s ullage is each tank''s capacity less its stock, summed, 11767.300 m3. The forecourt''s ullage at reorder is capacity less the reorder level, 28125.00 litres. 10123.000 m3 is the farm''s pumpable stock, 11875.00 litres the reorder level, and 21845.000 m3 and 37500.00 litres are the working capacity and the usable tank litres.'),
  ('supply', 'intermediate', 'final', null, 35, 'The farm prints 3.8345 days of cover to four decimals; the station prints 1.04 cover days. Why only two decimals at the station?', '["The station''s litres print to two decimals, so its cover does too.", "The station''s cover is in hours.", "The station''s cover is a floor, since the delivery does not fit.", "The engine rounds station cover days to two."]'::jsonb, 3, 'cover days = usable tank litres / litres a day, and the engine rounds it to two decimals, so it prints to two where the farm''s cover and turns print to four.'),
  ('supply', 'intermediate', 'final', null, 36, 'The rack refuses a bay count of 2.5, and fleetSizing prints 58 trucks for 38.181818 trips needed. How do the two treat a count that is not whole?', '["Both round up to the next whole unit and report the spare.", "The rack refuses a typed fraction; the fleet rounds a computed one up.", "Both refuse any input that is not whole.", "The rack rounds up; the fleet refuses a fractional truck."]'::jsonb, 1, 'A bay count is an input that must be a whole number, one or more. The fleet''s trucks are computed, and the engine takes the ceiling and reports the spare it buys, 0.345262 trips a day.'),
  ('supply', 'intermediate', 'final', null, 37, 'Which two notes say a carbon figure is absent because no emission factor was supplied?', '["The depot''s no-density note and the lane''s diesel note, both about factors.", "The depot''s no-density note and assumedZero.", "The depot''s no-emission-factor note and the lane''s diesel note.", "The lane''s floor and the station''s warning."]'::jsonb, 2, 'throughputEconomics: "No emission factor supplied, so the carbon side is not computed." truckingEconomics: "No diesel emission factor supplied, so the carbon figure is absent rather than zero." The no-density note is about the loss''s weight.'),
  ('supply', 'intermediate', 'final', null, 38, 'At the forecourt the mean wait is 2.2083 minutes at 6 nozzles. Which cars does it average over?', '["Every car, including the ones that drive straight to a free nozzle.", "Only the cars that queue, as the rack''s 60.0000 minutes does.", "Only the cars in the peak hour that find the nozzles full.", "The cars that queue plus their time at the nozzle."]'::jsonb, 0, 'The forecourt is rackQueue with nozzles for bays, so its mean wait averages over every arrival, as the rack''s 47.2652 minutes does. The 60.0000 minutes the digest works out for the rack averages the trucks that queue.'),
  ('supply', 'intermediate', 'final', null, 39, 'The daily count of 216 trucks at the rack sits beside days of cover of 3.8345. Why does the farm not use the truck count?', '["The count is per hour, and the farm needs a day.", "The farm counts its liftings in trucks per hour.", "The count is an Erlang B figure.", "The rack model carries no load volume."]'::jsonb, 3, 'The farm table labels its divisor daily throughput (liftings), in m3, and with no daily throughput the farm gives days of cover none. The rack''s 216 is labelled trucks per day at this arrival rate, and its inputs are arrivals, load minutes and bays, with no volume.'),
  ('supply', 'intermediate', 'final', null, 40, 'Both the lane''s floor and the no-density period show the engine stopping at a missing link. What does each still print?', '["Both print none for everything after the gap and before it.", "The lane prints 13.2401 naira a litre; the period prints its margin of 4988.00 USD.", "The lane prints 15.0704 naira; the period prints its loss tonnes.", "The lane refuses; the period prints its emissions of 2913.7320."]'::jsonb, 1, 'Nothing before a gap is lost and nothing after it is guessed. The lane with no truck capital prints a floor with Truck depreciation named; the period with no density prints its money side and reads none from loss tonnes on.'),
  ('supply', 'intermediate', 'final', null, 41, 'The rack''s refusal says to add a bay, and a forecourt can add a nozzle. Which input do both change?', '["The arrivals in the peak hour.", "The service minutes.", "The c of the M/M/c queue.", "The offered load."]'::jsonb, 2, 'Bays at the rack and nozzles at the forecourt are the same input of one queue model. Adding one lowers the utilisation and leaves the offered load where it was, 3.6000 erlangs at IBAFO''s rack.'),
  ('supply', 'intermediate', 'final', null, 42, 'The farm turns 44.1108 times a year, and IBAFO earns an invented throughput fee. What ties the turns to the fee''s revenue?', '["Turns set the fee rate the engine applies to each cubic metre.", "Each turn adds the invented fixed cost of 9400.00 USD once more.", "The margin per m3 of 1.89 USD is paid once for each turn.", "Both are formed from throughput in the engine''s formulas."]'::jsonb, 3, 'Turns = daily throughput x 365 / working capacity, and revenue = throughput x fee. The fee, 7.80 USD/m3, is an invented input the caller types.');
